// **React Native as an application framework: the web, and an Android APK.**
//
// One Expo project, two targets. The **web bundle** is what Saltcorn serves on
// the application's subdomain: `expo export --platform web` renders the React
// Native components through react-native-web into a static SPA, which is served,
// mounted and reloaded exactly as a React or Vue app is. The **Android APK** is a
// build *target* (`targets.android` below): `expo prebuild` writes the native
// project and Gradle builds a release APK from it, left in the file store for the
// admin to take away. It needs an Android SDK and a JDK, whose directories are
// this module's own settings (Settings → Modules → React Native): they are set
// as `ANDROID_HOME` and `JAVA_HOME` on the APK build, so the server does not
// depend on the shell that started it. The web build needs neither.
//
// What it is *not*
// ----------------
// A second serving implementation, or a second client generator. As for Vue:
// `src/feldspar/client.ts`, its helper, `schema.sql` and `SKILL.md` are written
// by **Saltcorn** from the application's own API. This module writes the half
// that is React Native's: the hooks, the screens, the shell.
//
// Why the screens use no DOM
// --------------------------
// A screen that renders `<div>` works on the web and nowhere else. Every screen
// is React Native's components and `StyleSheet`, which is what lets the same
// source become both targets.
//
// The conventions, for a project named `todo` in file store `apps`
// -----------------------------------------------------------------
// | path | what it is |
// |---|---|
// | `todo/` | the project (Expo) |
// | `todo/dist` | the web bundle Saltcorn serves |
// | `todo/android/` | the native project `expo prebuild` writes — generated, ignored by git |
// | `todo/src/feldspar/` | generated: rewritten on every build, never edited |
// | `todo/src/screens/*.tsx` | one screen per exposed table — yours from here |

/** The header every regenerated file carries, so the boundary between "yours"
 * and "ours" is visible in the file rather than only in the documentation. */
const GENERATED = `// Code generated by Saltcorn. DO NOT EDIT.
// Rewritten on every build; edits here are lost.
`;

// ---------------------------------------------------------------------------
// The declaration
// ---------------------------------------------------------------------------

/** The two settings `react` and `vue` ask for, for the same reasons, and one of
 * this framework's own: where a phone reaches the server. */
const config_fields = [
  {
    name: "store",
    label: "File store",
    type: "String",
    required: true,
    server_query: "file_stores",
  },
  {
    name: "project",
    label: "Project directory (blank for the store root)",
    type: "String",
    default: "",
  },
  {
    name: "mobile_url",
    label: "Server URL for the mobile app (blank: the application's URL)",
    type: "String",
    default: "",
  },
];

/** Where the source is and how the web bundle builds — Vue's layout: the same
 * output directory and the same generated runtime. */
const build = {
  store: "{{ store }}",
  source: "{{ project }}",
  output: "{{ project }}/dist",
  command: "npm run build",
  install: { command: "npm install", marker: "node_modules" },
  runtime: "{{ project }}/src/feldspar",
  client: "client.ts",
};

/** The React and Vue policy plus **one** widening: `style-src 'unsafe-inline'`.
 *
 * `StyleSheet.create` on the web is react-native-web's runtime style engine: it
 * writes the app's styles into a `<style>` element it creates, and it has no
 * nonce support. That is the injection the React scaffold avoids by using a CSS
 * file; a React Native screen has no CSS file to use. Scripts stay strict — no
 * `'unsafe-inline'` and no `'unsafe-eval'` in `script-src`, which the baseline's
 * `default-src 'self'` governs. */
const csp = {
  "style-src": ["'self'", "'unsafe-inline'"],
  "img-src": ["'self'", "data:"],
  "font-src": ["'self'", "data:"],
  "connect-src": ["'self'"],
  "object-src": ["'none'"],
  "base-uri": ["'self'"],
  "frame-ancestors": ["'none'"],
};

/** The module's own settings, shown on the Modules tab: where this machine's
 * Android toolchain is. They belong to the module rather than to an application
 * because every application of this framework builds with the same SDK. Saving
 * them reloads the module, which is when `frameworks` below reads them again. */
const configuration_workflow = () => ({
  steps: [
    {
      name: "Android toolchain",
      form: {
        fields: [
          {
            name: "android_home",
            label: "Android SDK directory (ANDROID_HOME)",
            type: "String",
          },
          {
            name: "java_home",
            label: "JDK directory (JAVA_HOME)",
            type: "String",
          },
        ],
      },
    },
  ],
});

/** The builds offered beside the web bundle. The artifact is where Gradle
 * leaves a release APK in the project `expo prebuild` writes; the environment
 * is this module's settings. A setting left blank is left out, so the build
 * falls back to the server's own environment. */
function targets(configuration) {
  return {
    android: {
      label: "Android APK",
      command: "npm run build:android",
      artifact: "{{ project }}/android/app/build/outputs/apk/release/app-release.apk",
      env: {
        ANDROID_HOME: configuration.android_home || "",
        JAVA_HOME: configuration.java_home || "",
      },
      // Checked before a build starts and shown on the button: a server without
      // the toolchain says so at once, instead of Gradle saying it minutes into a
      // build. Met by the settings above, or by the server's own environment.
      requires: [
        {
          env: "ANDROID_HOME",
          directory: true,
          hint: "Set the Android SDK directory under Settings → Modules → React Native.",
        },
        {
          env: "JAVA_HOME",
          directory: true,
          hint: "Set the JDK directory under Settings → Modules → React Native.",
        },
      ],
    },
  };
}

/** The builder agent's system prompt: its role and this platform. */
const builder_prompt = `You build the \`{{ app }}\` application, an Expo (React Native) project \
served on the web at the \`{{ subdomain }}\` subdomain and built into an Android APK. Its source \
is in the \`{{ store }}\` file store under \`{{ root }}\`, and your file tools are scoped to \
exactly that directory.

Four conventions of this framework: \`src/feldspar/\` is generated from the application's own \
API — its typed client and hooks are rewritten on every build, so read it to learn what data is \
available but never edit it; the application's data is reached through that client, never by \
talking to a database; screens are components under \`src/screens/\`, registered in \
\`src/routes.tsx\`; and screens use React Native's components and \`StyleSheet\` only — no DOM \
elements and no CSS files — so that the same source runs on the web and on a phone.`;

// ---------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------

/** A path under the project. `""` is the project root. */
const at = (dir, name) => (dir ? `${dir}/${name}` : name);

/** The row/insert/update types `hooks.ts` itself names — what it *uses*, which
 * is not what it re-exports; an unused type import fails `noUnusedLocals`. */
function usedRowTypes(table) {
  const used = [`${table.pascal}Row`];
  if (table.ops.create) used.push(`${table.pascal}Insert`);
  if (table.ops.update && table.pk) used.push(`${table.pascal}Update`);
  return used;
}

/** The named imports one file needs from a module, in a stable order. */
function importLine(names, from) {
  return names.length ? `import { ${names.join(", ")} } from "${from}";\n` : "";
}

// ---------------------------------------------------------------------------
// The generated runtime — React Native's half of `src/feldspar/`
// ---------------------------------------------------------------------------

/** `hooks.ts`: the React scaffold's hooks, unchanged in shape — a screen here
 * and a page in a React app read their data the same way. Hooks are React's, not
 * the DOM's, so nothing in this file is web-specific. */
function hooksTs(ctx) {
  const rowTypes = ctx.tables.flatMap(usedRowTypes);
  let out = GENERATED;
  out += `
import { useCallback, useEffect, useState, useSyncExternalStore } from "react";
import { Platform } from "react-native";

import { createClient, type ApiClient } from "./client";
import { APP_URL } from "./config";
`;
  if (rowTypes.length) out += `import type { ${rowTypes.join(", ")} } from "./client";\n`;
  out += `
/**
 * The app's typed API client. Endpoint paths already include the API mount.
 *
 * On the web the page's own origin is the application, so requests stay
 * relative. On a phone there is no page: they go to the application's URL.
 */
export const api: ApiClient = createClient({
  baseUrl: Platform.OS === "web" ? "" : APP_URL,
});

/** The state of one read: data, plus what is happening to it. */
export type Query<T> = {
  data: T | undefined;
  error: Error | undefined;
  loading: boolean;
  /** Re-run this query (and any other on the same table). */
  refresh: () => void;
};

/** The state of one write. */
export type Mutation<A> = {
  run: (arg: A) => Promise<void>;
  pending: boolean;
  error: Error | undefined;
};

// One version counter per table: every read subscribes to its table, every
// write bumps it.
const versions = new Map<string, number>();
const listeners = new Map<string, Set<() => void>>();

function versionOf(table: string): number {
  return versions.get(table) ?? 0;
}

function subscribe(table: string, listener: () => void): () => void {
  const set = listeners.get(table) ?? new Set<() => void>();
  listeners.set(table, set);
  set.add(listener);
  return () => set.delete(listener);
}

/** Discard what is cached for \`table\`, re-running every query over it. */
export function invalidate(table: string): void {
  versions.set(table, versionOf(table) + 1);
  listeners.get(table)?.forEach((l) => l());
}

/**
 * Read something from the API, cached under \`table\` and re-run whenever
 * anything writes to that table. Exported so a custom endpoint can join the
 * same cache.
 */
export function useQuery<T>(table: string, load: () => Promise<T>): Query<T> {
  const version = useSyncExternalStore(
    (cb) => subscribe(table, cb),
    () => versionOf(table),
    () => 0,
  );
  const [state, setState] = useState<{
    data: T | undefined;
    error: Error | undefined;
    loading: boolean;
  }>({ data: undefined, error: undefined, loading: true });

  useEffect(() => {
    let cancelled = false;
    setState((s) => ({ ...s, loading: true }));
    load().then(
      (data) => !cancelled && setState({ data, error: undefined, loading: false }),
      (e: unknown) =>
        !cancelled &&
        setState({
          data: undefined,
          error: e instanceof Error ? e : new Error(String(e)),
          loading: false,
        }),
    );
    return () => {
      cancelled = true;
    };
    // \`load\` is rebuilt every render; the table's version is what changes the answer.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [table, version]);

  return { ...state, refresh: () => invalidate(table) };
}

/**
 * Write through \`fn\`, then invalidate \`table\` so every query over it re-runs.
 * Exported for the same reason as \`useQuery\`.
 */
export function useMutation<A>(table: string, fn: (arg: A) => Promise<unknown>): Mutation<A> {
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<Error | undefined>(undefined);
  const run = useCallback(
    async (arg: A) => {
      setPending(true);
      setError(undefined);
      try {
        await fn(arg);
        invalidate(table);
      } catch (e: unknown) {
        setError(e instanceof Error ? e : new Error(String(e)));
      } finally {
        setPending(false);
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [table],
  );
  return { run, pending, error };
}
`;
  for (const table of ctx.tables) out += `\n${tableHooks(table)}`;
  return out;
}

/** One table's hooks, over that table's own object on the client. The
 * row-addressed ones follow the endpoints: the API projects them only for a
 * table with a single-column key. */
function tableHooks(table) {
  const { name, pascal, client, pk, pk_ts_type: key } = table;
  const exported = [`type ${pascal}Row`];
  if (table.ops.create || table.ops.update) {
    exported.push(`type ${pascal}Insert`, `type ${pascal}Update`);
  }

  let out = `// --- ${name} ---

export { ${exported.join(", ")} } from "./client";

/** Every row of \`${name}\`, re-fetched when anything writes to it. */
export function use${pascal}(): Query<${pascal}Row[]> {
  return useQuery("${name}", () => api.${client}.list());
}
`;
  if (table.ops.create) {
    out += `
/** Insert a row into \`${name}\`. */
export function useCreate${pascal}(): Mutation<${pascal}Insert> {
  return useMutation("${name}", (row) => api.${client}.create(row));
}
`;
  }
  if (pk) {
    out += `
/** One row of \`${name}\`, selected from the list by its primary key. */
export function use${pascal}Row(id: ${key}): Query<${pascal}Row | undefined> {
  const rows = use${pascal}();
  return { ...rows, data: rows.data?.find((r) => r.${pk} === id) };
}
`;
    if (table.ops.update) {
      out += `
/** Change a row of \`${name}\`. */
export function useUpdate${pascal}(): Mutation<{ id: ${key}; row: ${pascal}Update }> {
  return useMutation("${name}", ({ id, row }) => api.${client}.update(id, row));
}
`;
    }
    if (table.ops.delete) {
      out += `
/** Delete a row of \`${name}\`. */
export function useDelete${pascal}(): Mutation<${key}> {
  return useMutation("${name}", (id) => api.${client}.delete(id));
}
`;
    }
  }
  return out;
}

/** `config.ts`: where the application is, for a client that is not a page on
 * it. Rewritten on every build, so a changed setting reaches the next APK. */
function configTs(ctx) {
  return `${GENERATED}
/**
 * Where a phone sends its API requests; on the web they stay relative to the
 * page. It is the application's "Server URL for the mobile app" setting, or its
 * own URL when that is blank. A phone cannot reach \`localhost\`: for an emulator
 * or a device on the LAN, set that setting (e.g. \`http://<subdomain>.10.0.2.2.nip.io:3032\`),
 * list the domain in the server's \`extra_base_domains\`, and build again.
 */
export const APP_URL = ${JSON.stringify(mobileUrl(ctx))};
`;
}

/** The generated directory's own README. */
function runtimeReadme(ctx) {
  const list = ctx.tables.length
    ? ctx.tables.map((t) => `- \`use${t.pascal}()\` — every row of \`${t.name}\``).join("\n")
    : "- (this application exposes no tables yet)";
  return `# \`${ctx.runtime}\` — generated

Everything in this directory is written by Saltcorn and **rewritten on every
build**. Edits here are lost. It is generated from the \`${ctx.app.name}\`
application's own API, so adding a table or a column in the admin UI makes the
matching types and hooks exist at the next build.

| file | what it is |
|---|---|
| \`client.ts\` | the typed API client: one method per endpoint this application exposes |
| \`helper.ts\` | how a request is made and how a failure is reported — the same in every application |
| \`hooks.ts\` | React hooks over that client, one set per table |
| \`config.ts\` | the application's URL, which a phone sends its requests to |
| \`schema.sql\` | a description of this application's tables, for writing SQL against |
| \`SKILL.md\` | the half of the application that is *not* in this repository |

## The hooks

${list}

A write is a \`Mutation\`: call \`run\`, and every query over that table re-runs.

## The API is missing something I need

Add a custom SQL query to the application and it becomes a typed method on
\`client.ts\` at the next build:

\`\`\`sh
feldspar api add-query --app ${ctx.app.subdomain} --name recentPosts \\
  --sql "SELECT * FROM posts ORDER BY published DESC LIMIT :n"
\`\`\`
`;
}

// ---------------------------------------------------------------------------
// The project, written once
// ---------------------------------------------------------------------------

/** The versions are one Expo SDK's (57), taken together: Expo pins the
 * `react-native`, `react-dom` and `react-native-web` it was tested with, and a
 * project that mixes SDKs builds on neither target.
 *
 * `build` is the web bundle Saltcorn serves. `build:android` is the Android
 * target: `expo prebuild` writes the native project into `android/` (generated,
 * ignored by git), and Gradle builds a release APK from it. A release build
 * because it carries its JavaScript inside — a debug one would need a Metro dev
 * server running beside the phone. `--no-daemon` because it is a server that
 * runs it, and a Gradle daemon left behind is a gigabyte nobody asked for. */
function packageJson(ctx) {
  const buildProperties = cleartext(ctx)
    ? `,\n    "expo-build-properties": "~57.0.22"`
    : "";
  return `{
  "name": "${ctx.name}",
  "private": true,
  "version": "0.1.0",
  "main": "index.ts",
  "scripts": {
    "start": "expo start",
    "build": "tsc --noEmit && expo export --platform web --output-dir dist",
    "typecheck": "tsc --noEmit",
    "build:android": "expo prebuild --platform android --no-install && cd android && ./gradlew assembleRelease --no-daemon"
  },
  "dependencies": {
    "@expo/metro-runtime": "~57.0.16",
    "expo": "~57.0.25",
    "react": "19.2.3",
    "react-dom": "19.2.3",
    "react-native": "0.86.3",
    "react-native-web": "~0.21.0"${buildProperties}
  },
  "devDependencies": {
    "@types/react": "~19.2.2",
    "typescript": "~6.0.3"
  }
}
`;
}

/** Where the APK sends its requests: the `mobile_url` setting when the admin
 * gave one, the application's own URL otherwise. Without a trailing slash, since
 * the client appends paths that start with one. */
function mobileUrl(ctx) {
  const setting = ((ctx.settings || {}).mobile_url || "").trim();
  return (setting || ctx.app.url || "").replace(/\/+$/, "");
}

/** Whether the APK reaches its server over plain `http://` — a development
 * server. Android refuses cleartext traffic from a release build unless the app
 * says otherwise, so such an app says otherwise; one served over HTTPS does not
 * carry the permission it does not need. Decided when the project is written. */
const cleartext = (ctx) => /^http:/i.test(mobileUrl(ctx));

/** The Android application id: `com.feldspar.<subdomain>`, as Java package
 * segments — lowercase letters, digits and `_`, starting with a letter. */
function androidPackage(ctx) {
  let segment = String(ctx.app.subdomain || ctx.name || "app")
    .toLowerCase()
    .replace(/[^a-z0-9_]/g, "_");
  if (!/^[a-z]/.test(segment)) segment = `app_${segment}`;
  return `com.feldspar.${segment}`;
}

/** Expo's app configuration. `web.output: "single"` is an SPA — one
 * `index.html` Saltcorn's fallback serves for every path. */
function appJson(ctx) {
  const config = {
    expo: {
      name: ctx.app.name,
      slug: ctx.name,
      version: "1.0.0",
      orientation: "portrait",
      userInterfaceStyle: "light",
      android: { package: androidPackage(ctx) },
      web: { output: "single", bundler: "metro" },
    },
  };
  if (cleartext(ctx)) {
    config.expo.plugins = [
      ["expo-build-properties", { android: { usesCleartextTraffic: true } }],
    ];
  }
  return `${JSON.stringify(config, null, 2)}\n`;
}

/** Expo's base settings (it knows what Metro and React Native expect), with the
 * strictness every generated project here has. `tsc --noEmit` runs before the
 * web export on purpose: the client is regenerated from the app's endpoints on
 * every build, so a removed table fails the build naming the call site. */
const TSCONFIG = `{
  "extends": "expo/tsconfig.base",
  "compilerOptions": {
    "strict": true,
    "noUnusedLocals": true,
    "noUnusedParameters": true,
    "noFallthroughCasesInSwitch": true,
    "skipLibCheck": true
  },
  "include": ["index.ts", "src"]
}
`;

/** The generated runtime is part of the source; `android/` and `ios/` are what
 * `expo prebuild` writes, and are rewritten from `app.json` on every target
 * build; `build-logs/` is where the server writes each target build's log. The last lines are the session files `feldspar auth token` writes. */
const GITIGNORE = `node_modules
dist
.expo
android
ios
build-logs
*.local
.feldspar-session
.feldspar-session.json
`;

/** The entry point on every platform: Expo registers the root component with
 * `AppRegistry` and, on the web, mounts it into its own `#root`. */
const INDEX_TS = `import { registerRootComponent } from "expo";

import Root from "./src/Root";

registerRootComponent(Root);
`;

/** The providers around the shell. */
function rootTsx(ctx) {
  const imports = [
    `import App from "./App";`,
    ...(ctx.auth ? [`import { AuthProvider } from "./auth";`] : []),
    `import { NavigationProvider } from "./navigation";`,
  ].join("\n");
  const app = ctx.auth
    ? `      <AuthProvider>
        <App />
      </AuthProvider>`
    : `      <App />`;
  return `${imports}

export default function Root() {
  return (
    <NavigationProvider>
${app}
    </NavigationProvider>
  );
}
`;
}

/** A navigator small enough to read: the current path in state, and — on the
 * web — kept in step with the address bar and the back button. On a phone it
 * has no back stack; React Navigation is the replacement when one is needed, and
 * the screens only ever call `navigate`. */
const NAVIGATION_TSX = `import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from "react";
import { Platform } from "react-native";

export type Navigation = {
  /** The current path within the app. */
  path: string;
  navigate: (path: string) => void;
};

const NavigationContext = createContext<Navigation | undefined>(undefined);

const startPath = (): string => (Platform.OS === "web" ? window.location.pathname : "/");

export function NavigationProvider({ children }: { children: ReactNode }) {
  const [path, setPath] = useState(startPath);

  useEffect(() => {
    if (Platform.OS !== "web") return;
    const onPop = () => setPath(window.location.pathname);
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);

  const navigate = useCallback((next: string) => {
    if (Platform.OS === "web" && next !== window.location.pathname) {
      window.history.pushState(null, "", next);
    }
    setPath(next);
  }, []);

  return (
    <NavigationContext.Provider value={{ path, navigate }}>{children}</NavigationContext.Provider>
  );
}

export function useNavigation(): Navigation {
  const navigation = useContext(NavigationContext);
  if (!navigation) throw new Error("useNavigation must be used inside <NavigationProvider>");
  return navigation;
}
`;

